  if (any(q >= vec3i(textureDimensions(dst)))) { return; }
  let srcDims = vec3i(textureDimensions(src));
  let last = srcDims - 1;
  let taps = vec3i(2) + (srcDims & vec3i(1));
  var sum = 0.0;
